package gen

import (
	"bytes"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// ErrContractDrift identifies generated files that do not match contract.yaml.
// The diagnostic code is stable for CLI and Agent consumers.
var ErrContractDrift = errors.New("APPKIT_GEN_CONTRACT_DRIFT")

// ContractDrift describes one generated filename. Reason is missing, stale, or
// not_regular; unrelated handwritten files are outside the generator's scope.
type ContractDrift struct {
	Path   string
	Reason string
}

// ContractDriftError reports every drifted generated file in filename order.
type ContractDriftError struct {
	Files []ContractDrift
}

func (err *ContractDriftError) Error() string {
	parts := make([]string, 0, len(err.Files))
	for _, file := range err.Files {
		parts = append(parts, file.Reason+" "+file.Path)
	}
	return ErrContractDrift.Error() + ": " + strings.Join(parts, "; ")
}

func (err *ContractDriftError) Unwrap() error { return ErrContractDrift }

// CheckContract compares the exact generated bytes with outDir without creating,
// deleting, or changing any target files. This checks generated consistency, not
// semantic compatibility with a previous contract version.
func CheckContract(inPath, outDir string) error {
	if inPath == "" || outDir == "" {
		return fmt.Errorf("gen contract -check 需要 -in <contract.yaml> 与 -dir <pkgdir>")
	}
	files, err := RenderContract(inPath)
	if err != nil {
		return err
	}
	var drift []ContractDrift
	for _, name := range contractFilenames {
		outPath := filepath.Join(outDir, name)
		info, err := os.Lstat(outPath)
		if errors.Is(err, os.ErrNotExist) {
			drift = append(drift, ContractDrift{Path: name, Reason: "missing"})
			continue
		}
		if err != nil {
			return fmt.Errorf("检查 %s: %w", outPath, err)
		}
		if !info.Mode().IsRegular() {
			drift = append(drift, ContractDrift{Path: name, Reason: "not_regular"})
			continue
		}
		actual, err := os.ReadFile(outPath)
		if err != nil {
			return fmt.Errorf("读取 %s: %w", outPath, err)
		}
		if !bytes.Equal(actual, files[name]) {
			drift = append(drift, ContractDrift{Path: name, Reason: "stale"})
		}
	}
	if len(drift) != 0 {
		return &ContractDriftError{Files: drift}
	}
	return nil
}
